// Recorded Russian goblin voices and original effects, embedded for offline play.
// Each clip is mono G.711 mu-law PCM at 16 kHz. Decode lazily into Web Audio.
(() => {
  'use strict';
  const samples = {
  "free1": "",
  "free2": "",
  "free3": "",
  "grab1": "",
  "grab2": "",
  "grab3": "",
  "rel1": "",
  "rel2": "",
  "shriek": "",
  "crash": "",
  "clamp": "",
  "spring": "",
  "tap": ""
};
  const buffers = new Map();
  const speaking = {
    free: ['free1', 'free2', 'free3'],
    grab: ['grab1', 'grab2', 'grab3'],
    release: ['rel1', 'rel2'],
  };
  const previous = {};
  let context, master, voice, operatorVoice;
  let gestureSeen = false;
  let enabled = true;
  let freeAfter = 0;
  let lastEffect = -Infinity;
  const live = new Set();
  let songBuffer, song, songGain, songStart, songOffset = 0;
  let motorBuffer, motor, motorGain, lastSpeed = 0;

  // A four-phrase garage jig in D minor. One step is a semiquaver.
  // Each lead note records start, length, and MIDI pitch.
  const hooks = [
    [[0,2,74],[3,1,77],[4,2,81],[7,1,79],[8,3,77],[12,2,74],[15,1,72]],
    [[0,2,74],[3,1,77],[4,2,81],[7,1,84],[8,3,81],[13,1,79],[14,2,77]],
    [[0,3,79],[4,1,79],[6,2,77],[9,2,74],[12,3,77]],
    [[0,2,76],[3,1,73],[4,2,76],[7,1,79],[8,3,81],[12,1,79],[14,1,73]],
    [[0,2,74],[3,1,77],[4,2,81],[7,1,84],[8,3,86],[13,1,84],[14,2,81]],
    [[0,3,82],[4,2,79],[7,1,77],[8,2,79],[11,1,82],[12,3,77]],
    [[0,2,76],[3,1,73],[4,3,76],[8,2,81],[11,1,79],[12,2,76],[15,1,73]],
    [[0,4,74],[6,2,69],[9,2,72],[12,2,74]],
  ];
  const harmony = [
    [50,53,57], [53,57,60], [55,58,62], [45,49,52],
    [50,53,57], [46,50,53], [45,49,52], [50,53,57],
  ];

  function makeSong() {
    const rate = 22050, step = 60 / (132 * 4);
    const frames = Math.round(16 * 16 * step * rate);
    const buffer = context.createBuffer(1, frames, rate);
    const mix = buffer.getChannelData(0);
    const tau = 2 * Math.PI;
    const tables = {};
    // Band-limited, softened pulse and triangle voices stay clear on a phone.
    for (const key of ['pipe', 'bass', 'pluck']) {
      const partials = key === 'pipe' ? [1,.26,.22,.15,.04,.09] :
        key === 'bass' ? [1,.38,.16,0,.09] : [1,0,-.18,0,.07];
      tables[key] = Float32Array.from({length:1024}, (_,i) =>
        partials.reduce((sum, gain, j) => sum + gain*Math.sin(tau*i*(j+1)/1024), 0));
    }
    function tone(position, length, midi, timbre, level) {
      const table = tables[timbre], freq = 440*Math.pow(2,(midi-69)/12);
      const start = Math.round(position*step*rate);
      const size = Math.round(length*step*rate);
      const tail = Math.min(size*.37,rate*.047), increment = freq*1024/rate;
      for (let i=0, phase=0; i<size; i++, phase+=increment) {
        const env = Math.min(1, i/(rate*.006), (size-i)/tail) * (1-.42*i/size);
        mix[(start+i)%frames] += table[(phase|0)&1023] * env * level;
      }
    }
    let seed = 1511;
    function percussion(position, kind, level) {
      const start = Math.round(position*step*rate);
      const size = Math.round(rate*(kind==='kick' ? .15 : kind==='snare' ? .11 : .036));
      let prior = 0;
      for (let i=0; i<size; i++) {
        const t = i/rate;
        seed = (Math.imul(seed,1664525)+1013904223) >>> 0;
        const noise = seed/2147483648-1, bright = (noise-prior)*.5;
        let v;
        if (kind==='kick') v = Math.sin(tau*(60*t+1.9*(1-Math.exp(-t*38))))*Math.exp(-26*t);
        else if (kind==='snare') v = (.7*bright+.28*Math.sin(tau*192*t))*Math.exp(-38*t);
        else v = bright*Math.exp(-86*t);
        mix[(start+i)%frames] += v*level*Math.min(1,i/20,(size-i)/35);
        prior = noise;
      }
    }
    for (let bar=0; bar<16; bar++) {
      const phrase = bar%8, start = 16*bar, [root, third, fifth] = harmony[phrase];
      // In the second pass, a quieter low pipe answers the high lead.
      for (const [pos, len, pitch] of hooks[phrase]) {
        tone(start+pos,len*.92,pitch,'pipe',.31);
        if (bar>=8 && pos>=8) tone(start+pos+.07,len*.78,pitch-12,'pluck',.12);
      }
      for (const pos of [0,6,8,14]) {
        tone(start+pos,pos%8===0 ? 3.3 : 1.44,pos===6 || pos===8 ? fifth : root,'bass',.39);
      }
      for (const pos of [2,10]) {
        tone(start+pos,1.1,third+12,'pluck',.10);
        tone(start+pos,1.1,fifth+12,'pluck',.09);
      }
      percussion(start,'kick',.36);
      percussion(start+8,'kick',.3);
      percussion(start+4,'snare',.23);
      percussion(start+12,'snare',.26);
      for (const pos of [2,6,10,14]) percussion(start+pos,'hat',.12);
      if (phrase===3 || phrase===7) percussion(start+15,'snare',.14);
    }
    return buffer;
  }

  function playing() {
    return Boolean(context && enabled && gestureSeen && !document.hidden);
  }

  function startSong() {
    if (song || !playing()) return;
    songBuffer ??= makeSong();
    song = context.createBufferSource();
    songGain = context.createGain();
    song.buffer = songBuffer;
    song.loop = true;
    song.connect(songGain);
    songGain.connect(master);
    songStart = context.currentTime;
    songGain.gain.setValueAtTime(0, songStart);
    songGain.gain.linearRampToValueAtTime(.20,songStart+.09);
    song.start(songStart, songOffset);
  }

  function musicLevel(value) {
    if (!songGain) return;
    const now = context.currentTime;
    songGain.gain.cancelScheduledValues(now);
    songGain.gain.setTargetAtTime(value, now, value < .2 ? .035 : .13);
  }

  function makeMotor() {
    const rate = 22050;
    const result = context.createBuffer(1,rate,rate);
    const data = result.getChannelData(0);
    for (let i=0;i<rate;i++) {
      const t = 2*Math.PI*i/rate;
      const teeth = Math.sin(324*t+.58*Math.sin(54*t));
      data[i] = (.48*Math.sin(108*t)+.28*Math.sin(216*t)+.17*teeth+.07*Math.sin(756*t)) *
        (.88+.12*Math.cos(18*t));
    }
    return result;
  }

  function setMotion(value) {
    if (!playing()) return;
    const speed = Math.max(0,Math.min(1,Number(value) || 0));
    const now = context.currentTime;
    if (speed < .022) {
      if (motor && lastSpeed>0) {
        motorGain.gain.cancelScheduledValues(now);
        motorGain.gain.setTargetAtTime(0,now,.033);
      }
      lastSpeed=0;
      return;
    }
    if (!motor) {
      motorBuffer ??= makeMotor();
      motor = context.createBufferSource();
      motor.buffer = motorBuffer;
      motor.loop = true;
      motorGain = context.createGain();
      motorGain.gain.value=0;
      motor.connect(motorGain);
      motorGain.connect(master);
      motor.start();
    }
    motor.playbackRate.setTargetAtTime(.78+1.15*speed,now,.055);
    motorGain.gain.cancelScheduledValues(now);
    motorGain.gain.setTargetAtTime(.035+.14*speed,now,.035);
    // If input updates cease, let the drive wind down on its own.
    motorGain.gain.setTargetAtTime(0,now+.20,.04);
    lastSpeed=speed;
  }

  function silence() {
    if (!context) return;
    if (song) {
      songOffset=(songOffset+context.currentTime-songStart)%songBuffer.duration;
      song.stop(); song.disconnect(); songGain.disconnect();
      song=null; songGain=null;
    }
    if (motor) {
      motor.stop(); motor.disconnect(); motorGain.disconnect();
      motor=null; motorGain=null; lastSpeed=0;
    }
    for (const sound of live) {
      sound.level.gain.value=0;
      sound.source.stop();
    }
    voice=null; operatorVoice=null;
  }

  function unlock() {
    gestureSeen = true;
    if (!enabled || document.hidden) return;
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (!Audio) return;
    if (!context) {
      context = new Audio();
      master = context.createGain();
      master.gain.value = .82;
      master.connect(context.destination);
      // Start a source during the gesture as required by mobile WebKit.
      const warmup = context.createBufferSource();
      warmup.buffer = context.createBuffer(1, 1, context.sampleRate);
      warmup.connect(master);
      warmup.start();
      warmup.onended = () => warmup.disconnect();
    }
    if (context.state !== 'running') context.resume().catch(() => {});
    startSong();
  }

  function buffer(name, encoded) {
    if (buffers.has(name)) return buffers.get(name);
    const packed = atob(encoded || samples[name]);
    const result = context.createBuffer(1, packed.length, 16000);
    const data = result.getChannelData(0);
    for (let i = 0; i < packed.length; i++) {
      const b = ~packed.charCodeAt(i) & 255;
      const linear = (((b & 15) * 8 + 132) << ((b >> 4) & 7)) - 132;
      data[i] = (b & 128 ? -linear : linear) / 32768;
    }
    buffers.set(name, result);
    return result;
  }

  function emit(name, gain, rate = 1, delay = 0, encoded = null) {
    const source = context.createBufferSource();
    const level = context.createGain();
    const now = context.currentTime;
    source.buffer = buffer(name, encoded);
    source.playbackRate.value = rate;
    source.connect(level);
    level.gain.value = gain;
    level.connect(master);
    const sound = { source, level };
    live.add(sound);
    source.onended = () => {
      live.delete(sound);
      source.disconnect();
      level.disconnect();
      if (voice === sound) { voice = null; musicLevel(.20); }
      if (operatorVoice === sound) operatorVoice = null;
    };
    source.start(now + delay);
    return sound;
  }

  function fade(sound) {
    if (!sound) return;
    const t = context.currentTime;
    sound.level.gain.setTargetAtTime(0, t, .008);
    sound.source.stop(t + .04);
  }

  function choose(type) {
    const group = speaking[type];
    const available = group.filter(name => name !== previous[type]);
    previous[type] = available[Math.floor(Math.random() * available.length)];
    return previous[type];
  }

  function playOperator(index) {
    if (!playing() || context.state !== 'running' || voice) return 0;
    const line = window.operatorLines?.[index];
    if (!line || !line.pcm) return 0;
    operatorVoice = voice = emit('operator_' + index, .84, 1, 0, line.pcm);
    musicLevel(.072);
    const duration = operatorVoice.source.buffer.duration;
    freeAfter = Math.max(freeAfter, context.currentTime + duration + .65);
    return duration;
  }

  function play(type) {
    if (!enabled || !context || document.hidden) return;
    const now = context.currentTime;
    // Keep the operator intelligible while preserving immediate mechanical cues.
    if (operatorVoice) {
      if (type === 'miss' && now - lastEffect < .15) return;
      const cue = { grab:['clamp',.3], release:['spring',.2], miss:['tap',.2],
        fall:['shriek',.20], impact:['crash',.29] }[type];
      if (cue) emit(cue[0], cue[1]);
      if (type === 'miss') lastEffect = now;
      return;
    }
    if (type === 'free') {
      if (voice || now < freeAfter) return;
      freeAfter = now + 4.5 + Math.random() * 1.5;
      voice = emit(choose(type), .52, .98 + Math.random() * .08);
      musicLevel(.135);
      return;
    }
    if (type === 'grumble') {
      if (voice || now < freeAfter) return;
      freeAfter = now + 3.5;
      voice = emit(choose('grab'), .58, .88 + Math.random()*.06);
      musicLevel(.11);
      return;
    }
    if (type === 'miss') {
      if (now - lastEffect < .15) return;
      emit('tap', .38);
      lastEffect = now;
      return;
    }
    if (type === 'impact') {
      emit('crash', .88, .94 + Math.random() * .09);
      freeAfter = Math.max(freeAfter, now + 1.5);
      return;
    }
    if (type !== 'fall' && !speaking[type]) return;
    fade(voice);
    musicLevel(.10);
    freeAfter = Math.max(freeAfter, now + 2);
    if (type === 'fall') {
      voice = emit('shriek', .68, .96 + Math.random() * .1);
    } else {
      const grabbing = type === 'grab';
      emit(grabbing ? 'clamp' : 'spring', grabbing ? .73 : .34);
      voice = emit(choose(type), .72, .96 + Math.random() * .08, grabbing ? .11 : .04);
    }
  }

  function setEnabled(value) {
    enabled = Boolean(value);
    if (!enabled || document.hidden) silence();
    else if (gestureSeen) unlock();
  }

  document.addEventListener('visibilitychange', () => {
    if (document.hidden) silence();
    else if (enabled && gestureSeen) unlock();
  });
  window.garageSound = { unlock, play, setEnabled, setMotion, playOperator };
})();
